INSERT INTO swhonen_vpl VALUES ("NH7_45","017_7_45","NEH","7","45","45","Mabawabu wa malango: wazao wa Shalumu, Ateri, Talmoni, Akubu, Hatita na Shobai 138 ");
INSERT INTO swhonen_vpl VALUES ("NH7_46","017_7_46","NEH","7","46","46","Watumishi wa Hekalu: wazao wa Siha, Hasufa, Tabaothi, ");
INSERT INTO swhonen_vpl VALUES ("NH7_47","017_7_47","NEH","7","47","47","wazao wa Kerosi, Sia, Padoni, ");
INSERT INTO swhonen_vpl VALUES ("NH7_48","017_7_48","NEH","7","48","48","wazao wa Lebana, Hagaba, Shalmai, ");
INSERT INTO swhonen_vpl VALUES ("NH7_49","017_7_49","NEH","7","49","49","wazao wa Hanani, Gideli, Gahari, ");
